import { test, expect } from '@playwright/test';
const base = process.env.BASE_URL || 'http://127.0.0.1:8787';
test('지역에서 후보를 저장한다', async ({ page }) => {
  await page.goto(`${base}/demo/`);
  await page.getByLabel('지역', { exact: true }).selectOption('기흥구');
  await expect(page.locator('.library').first()).toContainText('기흥구');
  await page.getByRole('button', { name: '후보로 저장', exact: true }).first().click();
  await page.getByLabel('저장한 후보만', { exact: true }).check();
  await expect(page.locator('.library')).toHaveCount(1);
  await expect(page.getByRole('button', { name: '후보에서 빼기' })).toBeVisible();
});

import { test, expect } from '@playwright/test';
const base = process.env.BASE_URL || 'http://127.0.0.1:8787';
test('빈 검색에서 복구한다', async ({ page }) => {
  await page.goto(`${base}/demo/`);
  await page.getByLabel('이름·주소 검색').fill('없는도서관999');
  await expect(page.getByRole('heading', { name: '조건에 맞는 도서관이 없습니다.' })).toBeVisible();
  await page.getByRole('button', { name: '전체 도서관 보기' }).click();
  await expect(page.locator('.library')).toHaveCount(27);
});

import { test, expect } from '@playwright/test';
const base = process.env.BASE_URL || 'http://127.0.0.1:8787';
test('자료 실패를 안내한다', async ({ page }) => {
  await page.route('**/data/libraries.json', route => route.fulfill({
    status: 503, contentType: 'application/json', body: '{}'
  }));
  await page.goto(`${base}/demo/`);
  await expect(page.getByRole('heading', { name: '자료를 불러오지 못했습니다.' })).toBeVisible();
  await expect(page.getByRole('link', { name: '다시 시도', exact: true })).toBeVisible();
});
